     1|export type OwnerLocationClarificationIntent = 'ambiguous_where_are_we' | 'physical_location_unavailable';
     2|
     3|export type IVXOwnerAISemanticIntent =
     4|  | 'time_query'
     5|  | 'ambiguous_location'
     6|  | 'physical_location_unavailable'
     7|  | 'project_status'
     8|  | 'long_structured_response'
     9|  | 'multi_step_task'
    10|  | 'deal_review'
    11|  | 'bug_review'
    12|  | 'code_retrieval'
    13|  | 'explicit_tool_request'
    14|  | 'app_build_planning'
    15|  | 'self_developer_execution'
    16|  | 'daily_self_improvement'
    17|  | 'media_generation_3d'
    18|  | 'normal_question';
    19|
    20|export type IVXOwnerAIRouteDecision = 'clarification' | 'time_tool' | 'tool_grounded_gpt' | 'self_developer' | 'self_improvement' | 'gpt_conversation';
    21|
    22|export type IVXOwnerAIPlannerDecision = {
    23|  semanticIntent: IVXOwnerAISemanticIntent;
    24|  route: IVXOwnerAIRouteDecision;
    25|  useTools: boolean;
    26|  toolHints: string[];
    27|  requiresLongResponse: boolean;
    28|  requiresTaskDecomposition: boolean;
    29|  memoryMode: 'load_recent_and_persist_turn';
    30|  fallbackPolicy: 'fail_visible_not_canned';
    31|  reason: string;
    32|};
    33|
    34|function normalizePrompt(prompt: string): string {
    35|  return prompt.trim().toLowerCase().replace(/\s+/g, ' ');
    36|}
    37|
    38|/**
    39| * Deterministic exact-echo command detector (acceptance test B).
    40| *
    41| * When the owner sends an explicit "reply/respond/say exactly: <X>" instruction,
    42| * IVX must return <X> VERBATIM — proving the LATEST owner message is the one being
    43| * executed, with no LLM paraphrasing, no clarification hijack, and no truncation.
    44| * Returns the exact text to echo (preserving original casing/characters), or null.
    45| */
    46|export function resolveExactEchoCommand(prompt: string): string | null {
    47|  const raw = prompt.trim();
    48|  if (!raw) {
    49|    return null;
    50|  }
    51|  // Match: reply/respond/answer/say/repeat/echo [back] exactly [with][:] <payload>
    52|  const match = raw.match(/^(?:please\s+)?(?:reply|respond|answer|say|repeat|echo|output|return|print)\s+(?:back\s+)?exactly(?:\s+with)?\s*[:\-]?\s*([\s\S]+)$/i);
    53|  if (!match) {
    54|    return null;
    55|  }
    56|  let payload = match[1].trim();
    57|  // Strip a single pair of wrapping quotes the owner may have added around the payload.
    58|  const quoted = payload.match(/^(["'\u201c\u2018])([\s\S]+)(["'\u201d\u2019])$/);
    59|  if (quoted) {
    60|    payload = quoted[2].trim();
    61|  }
    62|  return payload.length > 0 ? payload : null;
    63|}
    64|
    65|/**
    66| * Detects a long, structured owner EXECUTION command or task block (e.g.
    67| * "BLOCK 28 Visitor-to-Investor Conversion Engine / Create: ... / Track: ...").
    68| *
    69| * These must NEVER be hijacked by short clarification intents (physical location,
    70| * time, manual-answer, infrastructure-runtime) just because the spec happens to
    71| * mention a keyword like "location", "backend", or "runtime" inside a much larger
    72| * instruction. The whole class of "IVX answered the wrong context" bugs comes from
    73| * a clarification regex matching a single word inside a long command and short-
    74| * circuiting before execution routing. When this returns true, the planner routes
    75| * the command to task decomposition and the handler skips every clarification gate.
    76| */
    77|export function isOwnerExecutionOrTaskBlock(prompt: string): boolean {
    78|  const raw = prompt.trim();
    79|  if (!raw) {
    80|    return false;
    81|  }
    82|  const normalized = normalizePrompt(prompt);
    83|
    84|  // Explicit "BLOCK N" / "STEP N" / "PHASE N" task headers are always task blocks.
    85|  if (/\b(block|step|phase)\s*\d+\b/.test(normalized)) {
    86|    return true;
    87|  }
    88|
    89|  // Structured spec markers the owner uses for feature/task blocks.
    90|  const specMarkerCount = (raw.match(/^\s*(create|track|stages?|capabilities|dashboard|requirements?|safety|store|return|show|build|objective|audit|capabilities?|metrics?)\s*:/gim) ?? []).length;
    91|  if (specMarkerCount >= 2) {
    92|    return true;
    93|  }
    94|
    95|  // Multi-line, sufficiently long instructions are treated as task blocks so a
    96|  // single keyword can never reroute them to a one-line clarification answer.
    97|  const lineCount = raw.split(/\n/).filter((line) => line.trim().length > 0).length;
    98|  if (raw.length >= 320 && lineCount >= 4) {
    99|    return true;
   100|  }
   101|
   102|  // Imperative engine/system/feature build commands ("... Conversion Engine",
   103|  // "build the ... system") that are also reasonably long.
   104|  if (raw.length >= 90 && /\b(engine|system|pipeline|module|platform|dashboard|workflow)\b/.test(normalized) && /\b(create|build|implement|add|wire|ship|deploy|design|develop)\b/.test(normalized)) {
   105|    return true;
   106|  }
   107|
   108|  // Production-execution signals — explicit owner commands to commit/push/deploy/
   109|  // verify on this system. These must NEVER be hijacked by short-circuit
   110|  // clarification gates (time/date, location, manual-answer) just because the
   111|  // prompt happens to contain a date phrase like "(today's date)" inside a larger
   112|  // deploy instruction. This closes the chat→worker narrative-only fallback gap:
   113|  // a prompt like "Bump the version marker to ...-2026-07-19 (today's date), commit
   114|  // to GitHub, deploy to Render, verify /health" must route to the developer
   115|  // executor, not return "The answer is 2019." as a math/time query.
   116|  const hasCommitSignal = /\b(commit|push\s+(?:to\s+)?github|github\s+main|pr\s*#\d)\b/.test(normalized);
   117|  const hasDeploySignal = /\b(deploy|render|trigger\s+a\s+deploy|live\s+commit|production\s+commit)\b/.test(normalized);
   118|  const hasVerifySignal = /\b(verify|verified\s+evidence|verify\s+the\s+live|live\s+runtime\s+commit|github\s+head|sha\s+match|\/health)\b/.test(normalized);
   119|  const hasMutationSignal = /\b(bump|update|change|edit|modify|patch|fix|migrate|rollback)\b/.test(normalized)
   120|    && /\b(version|marker|file|endpoint|route|table|policy|config|code|production)\b/.test(normalized);
   121|  const executionSignalCount = [hasCommitSignal, hasDeploySignal, hasVerifySignal, hasMutationSignal].filter(Boolean).length;
   122|  if (executionSignalCount >= 2) {
   123|    return true;
   124|  }
   125|
   126|  // App-scaffold / new-app-from-scratch signals — explicit owner commands to
   127|  // CREATE a new app, scaffold a new project, build a new module from scratch,
   128|  // or run a stress/load test. These are real code-production requests the
   129|  // senior developer worker handles (create_file patch operations), NOT
   130|  // planning/narrative prompts. Without this guard, the planner mis-routes
   131|  // them to app_build_planning → gpt_conversation (narrative GPT-4o answer)
   132|  // and the senior developer never runs. Closes the PARTIAL item gap where
   133|  // "create a new app from scratch" returned a narrative plan instead of
   134|  // real scaffolded files.
   135|  const hasAppScaffoldSignal = /\b(?:create|scaffold|build|generate)\s+(?:a\s+)?(?:new\s+)?(?:app|application|module|service)\s+(?:from\s+scratch|project|skeleton|shell|template|called\s+|named\s+)/i.test(normalized)
   136|    || /\bnew\s+app\s+from\s+scratch/i.test(normalized)
   137|    || /\bscaffold\s+(?:a\s+)?(?:new\s+)?(?:app|project|module)/i.test(normalized);
   138|  const hasStressTestSignal = /\bstress\s*test/i.test(normalized)
   139|    || /\bload\s*test/i.test(normalized)
   140|    || /\brun\s+a\s+(?:stress|load)\s+test/i.test(normalized);
   141|  if (hasAppScaffoldSignal || hasStressTestSignal || isServerBugFixRequest(normalized)) {
   142|    return true;
   143|  }
   144|
   145|  return false;
   146|}
   147|
   148|function asksForLongStructuredResponse(normalized: string): boolean {
   149|  return /\b(full\s+list|complete\s+list|list\s+all|enumerate|from\s+1\s+to\s+\d+|1\s*[-–to]+\s*\d+|one\s+to\s+\d+|\d{2,}\s+(?:items?|points?|things?|steps?|rows?|entries|checks?))\b/.test(normalized)
   150|    // Full / structured audits always need the long-response budget + auto-continuation.
   151|    || /\b(full\s+audit|complete\s+audit|end[-\s]?to[-\s]?end\s+audit|audit\s+(?:everything|all|end\s+to\s+end|one\s+by\s+one)|run\s+(?:a\s+)?full\s+audit|audit\s+\d{1,4}\s*[-–to]+\s*\d{1,4}|audit\s+from\s+1)\b/.test(normalized)
   152|    // Any explicit numeric range whose upper bound is large (e.g. "1-100", "1 to 2000").
   153|    || hasLargeExplicitRange(normalized);
   154|}
   155|
   156|export function hasLargeExplicitRange(normalized: string): boolean {
   157|  const match = normalized.match(/\b(?:from\s+)?1\s*(?:[-–]|to)\s*(\d{2,4})\b/);
   158|  if (match) {
   159|    const upper = Number.parseInt(match[1], 10);
   160|    return Number.isFinite(upper) && upper >= 30;
   161|  }
   162|  return false;
   163|}
   164|
   165|function asksForMultiStepTask(normalized: string): boolean {
   166|  return /\b(step[-\s]?by[-\s]?step|multi[-\s]?step|decompose|break\s+(?:it|this)?\s*down|task\s+decomposition|execution\s+plan|implementation\s+plan|roadmap|sequence)\b/.test(normalized)
   167|    || /\b(build|fix|audit|implement|ship|repair|improve)\b.{0,80}\b(plan|steps|phases|tasks)\b/.test(normalized);
   168|}
   169|
   170|export function asksForDealReview(normalized: string): boolean {
   171|  return /\b(review\s+(?:this\s+)?deal|deal\s+review|underwrite|underwriting|cap\s+rate|noi|cash[-\s]?on[-\s]?cash|real\s+estate\s+deal|investment\s+deal)\b/.test(normalized);
   172|}
   173|
   174|export function asksForBugReview(normalized: string): boolean {
   175|  return /\b(what\s+bugs?\s+do\s+you\s+see|find\s+bugs?|bug\s+review|bug\s+list|prioritized\s+bug\s+list|review\s+(?:the\s+)?bugs?|errors?\s+do\s+you\s+see|what\s+is\s+broken)\b/.test(normalized)
   176|    || /\binspect\b.{0,100}\b(?:chat|ai|assistant)\b.{0,100}\bbugs?\b/.test(normalized);
   177|}
   178|
   179|/**
   180| * Detects when the owner wants to SEE real source code from the repository —
   181| * file paths, functions, endpoints, queries, or a feature's implementation —
   182| * rather than execute a build/fix task. These requests must be grounded in the
   183| * live repo (code search) so the answer contains concrete files and source,
   184| * never a generic LLM guess or a clarification question.
   185| */
   186|export function asksForCodeRetrieval(normalized: string): boolean {
   187|  const codeNoun = /\b(code|source|source\s+code|snippet|implementation|function|method|class|file|files|file\s+path|endpoint|route|api\s+route|handler|query|queries|sql\s+quer(?:y|ies)|service|module|component|schema\s+definition)\b/;
   188|  const retrievalVerb = /\b(show|give|return|see|read|display|paste|get|list|find|reveal|provide|where\s+is|which\s+file|what\s+file|locate|share)\b/;
   189|  // "show me the analytics code", "return the analytics implementation", "where is the auth endpoint"
   190|  if (retrievalVerb.test(normalized) && codeNoun.test(normalized)) {
   191|    return true;
   192|  }
   193|  // Direct phrasings that always imply real code retrieval.
   194|  return /\b(source\s+code|code\s+for|implementation\s+of|implementation\s+details|actual\s+code|real\s+code|how\s+is\s+\w+\s+implemented|how\s+does\s+\w+\s+work\s+in\s+(?:the\s+)?code|file\s+path|function\s+name|endpoint\s+definition|database\s+quer(?:y|ies)\s+used)\b/.test(normalized);
   195|}
   196|
   197|/**
   198| * Detects open-ended app/product build requests like "build an app like TikTok",
   199| * "create a clone of Uber", "I want to build a marketplace app". These must NOT
   200| * fall through to a generic conversational timeline. They trigger a senior product-
   201| * engineering planning response: architecture proposal, module breakdown, required
   202| * repo/actions, execution plan, and a permission/capability check — not boilerplate.
   203| *
   204| * Deliberately excludes prompts that already point at THIS repo's concrete work
   205| * ("build the feature", "build this screen"), which belong to self-developer execution.
   206| */
   207|/**
   208| * Detects an owner request to GENERATE a 3D model / mesh / render (e.g.
   209| * "generate a 3d model of a villa", "create a 3D render of our product",
   210| * "make me a 3d mesh of a chair"). Routes to the owner 3D generation tool
   211| * (Meshy/Tripo direct, or a deterministic procedural Three.js preview).
   212| *
   213| * Deliberately excludes "build an app" / generic build requests by requiring an
   214| * explicit 3D/mesh/render target word.
   215| */
   216|export function asksToGenerate3DModel(normalized: string): boolean {
   217|  const genVerb = /\b(generate|create|make|build|render|design|produce|model|sculpt|give\s+me|i\s+want|i\s+need)\b/;
   218|  const threeDTarget = /\b(3d|three[\s-]?d)\b/;
   219|  const meshTarget = /\b(3d\s+model|3d\s+render|3d\s+mesh|3d\s+object|3d\s+asset|mesh|render)\b/;
   220|  if (!genVerb.test(normalized)) {
   221|    return false;
   222|  }
   223|  if (threeDTarget.test(normalized)) {
   224|    return true;
   225|  }
   226|  // "model/mesh/render" without "3d" only counts when paired with a clear object word.
   227|  return meshTarget.test(normalized) && /\b(model|mesh|render|object|asset|figure|statue|product|prototype|scene)\b/.test(normalized);
   228|}
   229|
   230|/**
   231| * Detects a short, imperative server bug/crash/fix request that must execute
   232| * via the senior-developer runtime rather than fall through to a conversational
   233| * GPT answer. Catches prompts like "fix server crash", "server is down", "fix
   234| * the server issue", "resolve the backend crash" — these are concrete in-repo
   235| * engineering tasks, not general questions. Without this signal the prompt is
   236| * too short to register as a task block and the reliability gate blocks the
   237| * GPT answer with a contradictory STATE: BLOCKED message.
   238| */
   239|export function isServerBugFixRequest(normalized: string): boolean {
   240|  // Imperative "fix server ..." / "fix the server ..." / "fix backend/api ..."
   241|  const fixServer = /\bfix\s+(?:the\s+)?(?:server|backend|api)\b/i.test(normalized);
   242|  // Declarative server/backend/api crash / is down / outage / failure / error
   243|  const serverIncident = /\b(?:server|backend|api)\s+(?:is\s+|are\s+)?(?:crash|crashes|crashed|down|outage|offline|failing|failure|failures|error|errors|bug|bugs|issue|issues)\b/i.test(normalized);
   244|  // Imperative "fix server crash" / "fix backend outage" / "fix api error" (with specific noun)
   245|  const fixServerSpecific = /\bfix\s+(?:the\s+)?(?:server|backend|api)\s+(?:crash|crashes|outage|error|errors|failure|failures|issue|issues|bug|bugs)\b/i.test(normalized);
   246|  return fixServer || serverIncident || fixServerSpecific;
   247|}
   248|
   249|export function asksToBuildApp(normalized: string): boolean {
   250|  // "build/create/make/design/develop ... an/a/another ... app/clone/platform/product/mvp/saas/marketplace/..."
   251|  const buildVerb = /\b(build|create|make|design|develop|spin\s+up|launch|clone|ship)\b/;
   252|  const appNoun = /\b(app|application|clone|platform|product|mvp|saas|marketplace|startup|website|web\s+app|mobile\s+app|social\s+(?:app|network|platform)|dating\s+app|delivery\s+app|fintech\s+app)\b/;
   253|  // "like X" / "such as X" / "similar to X" / "version of X" / "clone of X" strongly implies product planning.
   254|  const comparativeApp = /\b(?:app|clone|platform|product|version|something)\b[^.]{0,40}\b(?:like|similar\s+to|such\s+as)\b/;
   255|  const cloneOf = /\b(clone|version|copy)\s+of\s+\w+/;
   256|
   257|  // A build command aimed at the owner's OWN IVX system ("build the IVX engine",
   258|  // "create our investment platform", "finish the autonomous engine") is in-repo
   259|  // EXECUTION, not a request to scaffold a brand-new external product. It must never
   260|  // enter narrative "app planning" mode — it routes to the senior-developer runtime.
   261|  if (targetsOwnSystemBuild(normalized)) {
   262|    return false;
   263|  }
   264|  if (cloneOf.test(normalized) || comparativeApp.test(normalized)) {
   265|    return true;
   266|  }
   267|  if (buildVerb.test(normalized) && appNoun.test(normalized)) {
   268|    // Avoid hijacking concrete in-repo execution like "build the screen"/"build this feature".
   269|    const pointsAtThisRepoWork = /\b(this|that|the)\s+(feature|screen|fix|bug|endpoint|route|module|component|migration|page|function|test)\b/.test(normalized);
   270|    return !pointsAtThisRepoWork;
   271|  }
   272|  return false;
   273|}
   274|
   275|/**
   276| * Detects a build/execute command aimed at the owner's OWN IVX system rather than a
   277| * brand-new external app. These are concrete in-repo engineering jobs ("build the IVX
   278| * autonomous engine", "create our investor pipeline", "finish the conversion engine",
   279| * "implement the IVX dashboard module") and must EXECUTE end-to-end via the senior-
   280| * developer runtime — never get answered with an "Architecture Proposal / Phase 1-4"
   281| * narrative. The signal is a build verb plus either an explicit "IVX"/"our"/"my"
   282| * possessive or a system-component noun (engine, pipeline, module, workflow, dashboard,
   283| * system, platform) describing THIS product.
   284| */
   285|export function targetsOwnSystemBuild(normalized: string): boolean {
   286|  const buildVerb = /\b(build|create|implement|develop|add|wire|integrate|set\s*up|spin\s*up|ship|deploy|launch|configure|finish|complete|make|design|generate|code)\b/;
   287|  if (!buildVerb.test(normalized)) {
   288|    return false;
   289|  }
   290|  // Explicit reference to THIS product / owner's own system.
   291|  const ownProduct = /\bivx\b/.test(normalized)
   292|    || /\b(our|my|the)\s+(?:own\s+)?(?:autonomous\s+|investment\s+|global\s+|owner\s+)?(engine|pipeline|module|workflow|dashboard|system|platform|backend|api|app|product|crm|portal)\b/.test(normalized);
   293|  // System-component nouns that, paired with a build verb, mean in-repo execution.
   294|  const systemComponent = /\b(engine|pipeline|module|workflow|conversion\s+engine|investment\s+engine|autonomous\s+(?:engine|system|investment))\b/.test(normalized);
   295|  return ownProduct || systemComponent;
   296|}
   297|
   298|/**
   299| * Detects work-completion / "prove you are a senior developer" requests, e.g.
   300| * "finish and show proof you are a senior developer", "complete the task and prove it",
   301| * "act as a senior developer and finish this". These are engineering-execution
   302| * intents and must route to the senior-developer runtime — NEVER to a canned
   303| * audit/status report (the word "developer" + "proof"/"code" must not be misread
   304| * as an IVX free/control audit).
   305| */
   306|export function asksToFinishOrProveSeniorDeveloperWork(normalized: string): boolean {
   307|  // "finish and show proof / deploy / prove / push ...", "finish it/this/the task/now".
   308|  const finishWork = /\b(finish|finalize|finalise|wrap\s+up|complete|deliver)\b.{0,60}\b(it|this|that|task|job|work|build|feature|fix|deployment|deploy|code|implementation|now|today|and\s+(?:show|deploy|prove|push|test|verify|ship|finish|complete))\b/i.test(normalized)
   309|    || /\bfinish\s+and\b/i.test(normalized);
   310|  // "(act as|be|prove you are|show proof you are|you are) a senior developer/engineer".
   311|  const seniorDeveloperPersona = /\b(?:act\s+as|be|prove\s+(?:you\s+are|that\s+you\s+are|yourself)|show\s+(?:me\s+)?proof\s+(?:you\s+are|that\s+you\s+are)|demonstrate\s+(?:you\s+are|that\s+you\s+are)|you\s+are)\s+(?:a\s+)?(?:real\s+|true\s+)?senior\s+(?:software\s+)?(?:developer|engineer|dev)\b/i.test(normalized)
   312|    || /\bsenior\s+(?:software\s+)?(?:developer|engineer)\b.{0,40}\b(mode|now|finish|complete|execute|work|build|fix|deploy|prove|show\s+proof|do\s+it)\b/i.test(normalized);
   313|  return finishWork || seniorDeveloperPersona;
   314|}
   315|
   316|/**
   317| * Detects the owner's daily self-improvement command — the single entry point that
   318| * starts the autonomous "find issue → patch → test → commit → deploy → verify" loop
   319| * WITHOUT naming a specific file or bug. Phrasings: "improve IVX today", "fix one bug
   320| * today", "self improve", "run daily improvement". These must route to the dedicated
   321| * daily-improvement task so progress is durable + visible in the Live Developer Monitor,
   322| * never to a generic conversational answer.
   323| */
   324|export function asksToImproveIVXToday(prompt: string): boolean {
   325|  const normalized = normalizePrompt(prompt);
   326|  if (!normalized) {
   327|    return false;
   328|  }
   329|  return /\bimprove\s+ivx(?:\s+(?:today|now|daily|automatically))?\b/.test(normalized)
   330|    || /\b(?:run|start|kick\s*off|begin)\s+(?:the\s+|a\s+)?daily\s+(?:self[-\s]?)?improvement\b/.test(normalized)
   331|    || /\bdaily\s+self[-\s]?improvement\b/.test(normalized)
   332|    || /\bself[-\s]?improve(?:ment)?\b/.test(normalized)
   333|    || /\bfix\s+one\s+(?:real\s+)?(?:bug|issue|problem)(?:\s+(?:today|now))?\b/.test(normalized)
   334|    || /\bimprove\s+(?:the\s+)?(?:platform|app|system|codebase|product)\s+(?:today|now|daily|automatically)\b/.test(normalized);
   335|}
   336|
   337|/**
   338| * Detects the owner's opportunity-discovery command — "find today's best opportunity",
   339| * "best opportunity today", "find me an opportunity", "opportunity scan", "scan for
   340| * opportunities". Routes to the owner-gated Opportunity Intelligence Engine so the
   341| * answer is grounded in real scored opportunities (never a fabricated tip).
   342| */
   343|export function asksForBestOpportunity(prompt: string): boolean {
   344|  const normalized = normalizePrompt(prompt);
   345|  if (!normalized) {
   346|    return false;
   347|  }
   348|  return /\bfind\s+(?:me\s+|today'?s\s+|the\s+)?(?:best|top|highest[-\s]?upside)\s+(?:opportunit(?:y|ies)|deal|investment)\b/.test(normalized)
   349|    || /\b(?:best|top|highest[-\s]?upside)\s+opportunit(?:y|ies)\s+(?:today|now|right\s+now)\b/.test(normalized)
   350|    || /\b(?:today'?s\s+)?(?:best|top)\s+opportunit(?:y|ies)\b/.test(normalized)
   351|    || /\b(?:run|start|do)\s+(?:an?\s+)?opportunity\s+scan\b/.test(normalized)
   352|    || /\bscan\s+(?:for|the\s+market\s+for)\s+opportunit(?:y|ies)\b/.test(normalized)
   353|    || /\bfind\s+(?:me\s+)?(?:an?\s+)?opportunit(?:y|ies)\b/.test(normalized);
   354|}
   355|
   356|/**
   357| * Detects the owner's "find the best investor for Deal X" command — routes to the
   358| * BLOCK 27 best-investor workflow (search CRM → rank → draft intro → follow-up →
